import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useTier } from '../config/TierContext';
import { Tier } from '../config/tiers';

export const SIDEBAR_WIDTH = 268;

const DARK = '#1C1C1E';
const DARK_2 = '#2C2C2E';
const BRAND_PINK = '#FF2D55';
const TIERS: Tier[] = ['Starter', 'Essentials', 'Pro'];

const navItems: { path: string; label: string; icon: React.ReactNode; section?: string }[] = [
  {
    path: '/dashboard',
    label: 'Dashboard',
    section: 'Analytics',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <rect x="3" y="3" width="7" height="7" rx="1.5" />
        <rect x="14" y="3" width="7" height="7" rx="1.5" />
        <rect x="3" y="14" width="7" height="7" rx="1.5" />
        <rect x="14" y="14" width="7" height="7" rx="1.5" />
      </svg>
    ),
  },
  {
    path: '/analytics',
    label: 'Explore & Ask Stella',
    section: 'Tools',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" strokeLinecap="round" strokeLinejoin="round" />
        <path d="M8 10h8M8 14h5" strokeLinecap="round" />
      </svg>
    ),
  },
  {
    path: '/knowledge-hub',
    label: 'Knowledge Hub',
    section: 'Tools',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M4 19V5a2 2 0 0 1 2-2h4v16H6a2 2 0 0 0-2 2zm16 0V5a2 2 0 0 0-2-2h-4v16h4a2 2 0 0 1 2 2z" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
];

export default function Sidebar() {
  const location = useLocation();
  const { tier, setTier } = useTier();

  const linkStyle = (path: string): React.CSSProperties => {
    const active = location.pathname === path;
    return {
      display: 'flex',
      alignItems: 'center',
      gap: 12,
      textDecoration: 'none',
      fontSize: 13.5,
      fontWeight: active ? 600 : 400,
      color: active ? BRAND_PINK : 'rgba(255,255,255,0.65)',
      padding: '10px 12px',
      borderRadius: 8,
      backgroundColor: active ? 'rgba(255,45,85,0.14)' : 'transparent',
      transition: 'all 0.15s ease',
      marginBottom: 2,
    };
  };

  return (
    <aside
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        bottom: 0,
        width: SIDEBAR_WIDTH,
        backgroundColor: DARK,
        borderRight: '1px solid rgba(255,255,255,0.08)',
        display: 'flex',
        flexDirection: 'column',
        zIndex: 1000,
        boxSizing: 'border-box',
      }}
    >
      <div style={{ padding: '1rem 1.15rem 0.75rem', flexShrink: 0 }}>
        <div
          style={{
            color: 'rgba(255,255,255,0.4)',
            fontSize: 10,
            fontWeight: 600,
            letterSpacing: '1px',
            textTransform: 'uppercase',
            marginBottom: 8,
          }}
        >
          Access level (demo)
        </div>
        <div style={{ display: 'flex', backgroundColor: DARK_2, borderRadius: 8, padding: 3 }}>
          {TIERS.map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => setTier(t)}
              style={{
                flex: 1,
                textAlign: 'center',
                padding: '6px 2px',
                fontSize: 11,
                fontWeight: t === tier ? 600 : 500,
                color: t === tier ? DARK : 'rgba(255,255,255,0.6)',
                backgroundColor: t === tier ? '#ffffff' : 'transparent',
                borderRadius: 6,
                cursor: 'pointer',
                transition: 'all 0.15s ease',
                border: '1px solid transparent',
              }}
            >
              {t}
            </button>
          ))}
        </div>
        <p style={{ fontSize: 10.5, color: 'rgba(255,255,255,0.35)', margin: '8px 0 0', lineHeight: 1.4 }}>
          Starter limits filters and drill; Essentials hides AI actions; Pro enables Muse and full interactivity.
        </p>
      </div>

      <nav style={{ padding: '0.25rem 0.7rem 0.35rem', display: 'flex', flexDirection: 'column', flex: 1, overflowY: 'auto', minHeight: 0 }}>
        {navItems.map((item, idx) => {
          const prevSection = idx > 0 ? navItems[idx - 1].section : null;
          const showSectionHeader = item.section && item.section !== prevSection;
          return (
            <React.Fragment key={item.path}>
              {showSectionHeader && (
                <div
                  style={{
                    fontSize: 9.5,
                    fontWeight: 700,
                    letterSpacing: '0.08em',
                    textTransform: 'uppercase',
                    color: 'rgba(255,255,255,0.3)',
                    padding: idx === 0 ? '6px 12px 4px' : '14px 12px 4px',
                  }}
                >
                  {item.section}
                </div>
              )}
              <Link to={item.path} style={linkStyle(item.path)}>
                <span style={{ display: 'flex', alignItems: 'center', width: 22, justifyContent: 'center', color: 'inherit' }}>
                  {item.icon}
                </span>
                <span style={{ flex: 1, lineHeight: 1.35, display: 'flex', alignItems: 'center', gap: 6 }}>
                  {item.label}
                </span>
              </Link>
            </React.Fragment>
          );
        })}
        <div style={{ flex: 1, minHeight: 8 }} />
      </nav>

      <div
        style={{
          padding: '0.875rem 1.15rem',
          borderTop: '1px solid rgba(255,255,255,0.08)',
          display: 'flex',
          alignItems: 'center',
          gap: 10,
        }}
      >
        <div
          style={{
            width: 36,
            height: 36,
            background: `linear-gradient(135deg, ${BRAND_PINK} 0%, #FF6B8A 100%)`,
            borderRadius: '50%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            flexShrink: 0,
            color: '#fff',
            fontWeight: 700,
            fontSize: 13,
            letterSpacing: '-0.02em',
          }}
        >
          M
        </div>
        <div style={{ lineHeight: 1.35 }}>
          <div style={{ color: '#ffffff', fontWeight: 600, fontSize: 13, letterSpacing: '-0.01em' }}>Maison</div>
          <div style={{ color: 'rgba(255,255,255,0.4)', fontSize: 11.5 }}>{tier} · demo user</div>
        </div>
      </div>
    </aside>
  );
}
